String _agNorm(dynamic v) {
  if (v == null) return 'null';
  if (v is bool || v is num || v is String) return jsonEncode(v);
  if (v is List) return '[${v.map(_agNorm).join(',')}]';
  if (v is Set) { final x=v.map(_agNorm).toList()..sort(); return '{${x.join(',')}}'; }
  if (v is Map) {
